import React, { useState } from 'react';

const TABS = ["Harvested Hours", "Savings & ROI"];

export default function CVSavingsROI(){
  const [tab, setTab] = useState(TABS[0]);
  return (
    <div>
      <div className="tabs">
        {TABS.map(t => (
          <button key={t} className={`roi-tab ${tab===t?"active":""}`} onClick={() => setTab(t)}>
            {t}
          </button>
        ))}
      </div>
      <div className="tab-panel">
        <div className="muted">Savings and ROI — <b>{tab}</b> (to be populated)</div>
      </div>
    </div>
  );
}
